return ['domain'=>'mlab-core','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'it_IT','project-id-version'=>'MomentumLab Core 0.5.2','pot-creation-date'=>'2026-11-10 10:23+0000','po-revision-date'=>'2026-11-10 10:25+0000','messages'=>['MomentumLab Core'=>'MomentumLab Core','Shows the MomentumLab plugins with your license key, installs and activates them with one click, and keeps them up to date. Manages the GitHub read tokens for updates from private repositories.'=>'Mostra i plugin MomentumLab con la chiave di licenza, li installa e attiva con un clic e li mantiene aggiornati. Gestisce i token di lettura GitHub per gli aggiornamenti dai repository privati.','MomentumLab'=>'MomentumLab','https://momentumlab.ch'=>'https://momentumlab.ch','You are not allowed to do this. Ask an administrator.'=>'Non è consentito eseguire questa operazione. Chiedere a un amministratore.','This plugin is not in the list. Press "Reload list" and try again.'=>'Questo plugin non è nell’elenco. Premere «Ricarica elenco» e riprovare.','The list is up to date.'=>'L’elenco è aggiornato.','This plugin is not part of your license. Please contact MomentumLab.'=>'Questo plugin non fa parte della licenza. Contattare MomentumLab.','The plugin is installed and active.'=>'Il plugin è installato e attivo.','The plugin is not installed. Switch it on to install it.'=>'Il plugin non è installato. Attivarlo per installarlo.','The plugin is active.'=>'Il plugin è attivo.','The plugin is switched off. It stays installed.'=>'Il plugin è disattivato. Resta installato.','Fine'=>'OK','Warning'=>'Avviso','Problem'=>'Problema','Check now'=>'Verifica ora','Checks'=>'Controlli','Not checked yet. Press "Check now" to see the result.'=>'Non ancora verificato. Premere «Verifica ora» per vedere il risultato.','Alarm by e-mail'=>'Avviso via e-mail','If a new problem appears, an e-mail goes to these addresses, at most once a day for the same problem. Write one address per line. Leave it empty to switch the alarm off.'=>'In caso di nuovo problema viene inviata un’e-mail a questi indirizzi, al massimo una volta al giorno per lo stesso problema. Un indirizzo per riga. Lasciare vuoto per disattivare l’avviso.','Addresses for the alarm, one per line'=>'Indirizzi per l’avviso, uno per riga','Save'=>'Salva','Not checked yet'=>'Non ancora verificato','%s. Checked automatically every morning at 06:00.'=>'%s. Verifica automatica ogni mattina alle 06:00.','Health'=>'Stato','Checked: there is a problem. See the list for what to do.'=>'Verificato: c’è un problema. L’elenco indica cosa fare.','Checked: your website is fine.'=>'Verificato: il sito è in ordine.','Saved. The alarm is on.'=>'Salvato. L’avviso è attivo.','Saved. The alarm is off.'=>'Salvato. L’avviso è disattivato.','The installation did not work. Please try again, or contact MomentumLab.'=>'L’installazione non è riuscita. Riprovare oppure contattare MomentumLab.','File changes are blocked on this website. Ask your host or developer to allow them.'=>'Le modifiche ai file sono bloccate su questo sito. Chiedere all’hosting o allo sviluppatore di consentirle.','The plugin is already installed. Please switch it on in the list.'=>'Il plugin è già installato. Attivarlo nell’elenco.','The main file is missing in the download'=>'Il file principale manca nel download','Overview'=>'Panoramica','Plugins'=>'Plugin','Settings'=>'Impostazioni','No key'=>'Nessuna chiave','No license yet – free plugins work without one'=>'Nessuna licenza ancora – i plugin gratuiti funzionano senza','Active'=>'Attiva','Your license is active.'=>'La licenza è attiva.','Not active'=>'Non attiva','Open the settings to check your license key.'=>'Aprire le impostazioni per verificare la chiave di licenza.','License'=>'Licenza','Checked today at %s'=>'Verificato oggi alle %s','Checked on %s'=>'Verificato il %s','Website health'=>'Stato del sito','The first check runs tomorrow morning.'=>'La prima verifica avverrà domani mattina.','%d warning'=>'%d avviso' . "\0" . '%d avvisi','All good'=>'Tutto a posto','%1$d of %2$d fine'=>'%1$d su %2$d in ordine','%d update'=>'%d aggiornamento' . "\0" . '%d aggiornamenti','Up to date'=>'Aggiornato','%d active'=>'%d attivo/i','%d more unlocked'=>'%d altro/i sbloccato/i','License problem'=>'Problema di licenza','Open settings'=>'Apri impostazioni','View'=>'Visualizza','Update %s'=>'Aggiorna %s','Version %1$s is ready. You have %2$s.'=>'La versione %1$s è pronta. Hai la versione %2$s.','Update'=>'Aggiorna','%s is ready to install'=>'%s è pronto per l’installazione','Your license includes it. Switch it on to install it.'=>'La licenza lo include. Attivarlo per installarlo.','Install'=>'Installa','Notice'=>'Avviso','To do'=>'Da fare','Nothing to do. Everything is up to date.'=>'Niente da fare. Tutto è aggiornato.','Everything important about your website at a glance.'=>'Tutto l’essenziale del sito a colpo d’occhio.','How MomentumLab works'=>'Come funziona MomentumLab','One license key covers all MomentumLab plugins on this website. Updates arrive through WordPress as usual. If the license expires, the plugins keep running – only updates and Pro features pause until you renew.'=>'Una sola chiave di licenza copre tutti i plugin MomentumLab di questo sito. Gli aggiornamenti arrivano come di consueto tramite WordPress. Se la licenza scade, i plugin continuano a funzionare; sono sospesi solo gli aggiornamenti e le funzioni Pro, fino al rinnovo.','All'=>'Tutti','Available'=>'Disponibili','Filter plugins'=>'Filtra plugin','Installed, switched off'=>'Installati, disattivati','Not included in your license'=>'Non incluso nella licenza','Not installed yet'=>'Non ancora installati','Switch off %s'=>'Disattiva %s','Switch on %s'=>'Attiva %s','Update to %s ready'=>'Aggiornamento a %s pronto','Update now'=>'Aggiorna ora','No more updates: this unlock has expired. The plugin keeps running.'=>'Niente più aggiornamenti: questo sblocco è scaduto. Il plugin continua a funzionare.','Renew'=>'Rinnova','On request'=>'Su richiesta','Version %1$s · %2$s'=>'Versione %1$s · %2$s','Ask MomentumLab'=>'Chiedi a MomentumLab','Reload list'=>'Ricarica elenco','Switch on installs and activates. Switching off only deactivates; nothing is deleted.'=>'Attivare installa e attiva. Disattivare si limita a disattivare; non viene eliminato nulla.','Included unlocks'=>'Sblocchi inclusi','Advanced: GitHub access'=>'Avanzate: accesso GitHub','Only needed if MomentumLab asks you to. With a license, updates arrive without GitHub.'=>'Necessario solo se lo richiede MomentumLab. Con una licenza, gli aggiornamenti arrivano senza GitHub.','Usually you only enter the license key here once.'=>'Di solito la chiave di licenza va inserita qui una sola volta.','What happens when the license expires?'=>'Cosa succede quando la licenza scade?','Your website keeps running. Updates and Pro features pause until you renew. If the MomentumLab server is briefly unreachable, everything stays as it is for 7 days.'=>'Il sito continua a funzionare. Aggiornamenti e funzioni Pro restano sospesi fino al rinnovo. Se il server MomentumLab è irraggiungibile per breve tempo, tutto resta com’è per 7 giorni.','For private MomentumLab repositories, WordPress needs a read token from GitHub. It is stored encrypted and never shown.'=>'Per i repository privati MomentumLab, WordPress ha bisogno di un token di lettura GitHub. Viene salvato cifrato e non viene mai mostrato.','The token is set in wp-config.php (MLAB_GITHUB_TOKEN) and applies to all repositories.'=>'Il token è impostato in wp-config.php (MLAB_GITHUB_TOKEN) e vale per tutti i repository.','Your website has no security keys (AUTH_KEY, SECURE_AUTH_KEY) in wp-config.php. Without them a token cannot be stored safely. Ask your host or developer to add them.'=>'Il sito non ha chiavi di sicurezza (AUTH_KEY, SECURE_AUTH_KEY) in wp-config.php. Senza di esse un token non può essere salvato in sicurezza. Chiedere all’hosting o allo sviluppatore di aggiungerle.','Applies to'=>'Si applica a','Token'=>'Token','Last test'=>'Ultimo test','Actions'=>'Azioni','Applies to (organization, or organization/repository)'=>'Si applica a (organizzazione o organizzazione/repository)','Token from GitHub'=>'Token da GitHub','Save and test'=>'Salva e verifica','not tested yet'=>'non ancora verificato','Expires on %s.'=>'Scade il %s.','Test connection'=>'Verifica connessione','Remove'=>'Rimuovi','Please enter an organization (for example momentumlab-ch) or organization/repository.'=>'Inserire un’organizzazione (ad esempio momentumlab-ch) oppure organizzazione/repository.','The token is set in wp-config.php and cannot be changed here.'=>'Il token è impostato in wp-config.php e non può essere modificato qui.','This does not look like a GitHub token. A fine-grained token starts with github_pat_. Please copy it again from GitHub.'=>'Non sembra un token GitHub. Un token a granularità fine inizia con github_pat_. Copiarlo di nuovo da GitHub.','The token could not be encrypted because the server has neither sodium nor openssl. Ask your host to enable one of them.'=>'Il token non può essere cifrato perché sul server mancano sodium e openssl. Chiedere all’hosting di attivarne uno.','Token saved. Test: %s'=>'Token salvato. Verifica: %s','The saved token can no longer be read because the security keys of your website have changed. Please enter the token again.'=>'Il token salvato non può più essere letto perché le chiavi di sicurezza del sito sono cambiate. Inserirlo di nuovo.','This token no longer exists. Reload the page.'=>'Questo token non esiste più. Ricaricare la pagina.','The token has been removed.'=>'Il token è stato rimosso.','The MomentumLab server cannot be reached right now. Please try again in a few minutes.'=>'Il server MomentumLab non è raggiungibile al momento. Riprovare tra qualche minuto.','GitHub is not reachable right now. Please try again later.'=>'GitHub non è raggiungibile al momento. Riprovare più tardi.','Connection works.'=>'La connessione funziona.','GitHub rejects the token: it is wrong, expired or revoked. Please enter a new token.'=>'GitHub rifiuta il token: è errato, scaduto o revocato. Inserire un nuovo token.','The token has no read access. Please grant "Contents: Read" on GitHub.'=>'Il token non ha accesso in lettura. Concedere «Contents: Read» su GitHub.','The repository is not visible with this token. Please allow access to this repository on GitHub.'=>'Il repository non è visibile con questo token. Consentire l’accesso a questo repository su GitHub.','Unexpected response from GitHub (status %d).'=>'Risposta imprevista da GitHub (stato %d).','Website reachable'=>'Sito raggiungibile','The home page does not respond: %s'=>'La home page non risponde: %s','The home page returns error code %d.'=>'La home page restituisce l’errore %d.','Responds in %s s.'=>'Risponde in %s s.','This is slow: check caching and the server.'=>'È lento: verificare la cache e il server.','SSL certificate'=>'Certificato SSL','The website does not use HTTPS. Ask your host to set up an SSL certificate.'=>'Il sito non usa HTTPS. Chiedere all’hosting di installare un certificato SSL.','The expiry date could not be read.'=>'Non è stato possibile leggere la data di scadenza.','Valid for another %1$d days (until %2$s).'=>'Valido ancora per %1$d giorni (fino al %2$s).','Does the certificate not renew by itself? Check with your host (e.g. Plesk, Let’s Encrypt).'=>'Il certificato non si rinnova da solo? Verificare con l’hosting (ad es. Plesk, Let’s Encrypt).','Updates'=>'Aggiornamenti','Everything is up to date.'=>'Tutto è aggiornato.','%d plugin update'=>'%d aggiornamento plugin' . "\0" . '%d aggiornamenti plugin','%d theme update'=>'%d aggiornamento tema' . "\0" . '%d aggiornamenti tema','WordPress update'=>'Aggiornamento di WordPress','pending.'=>'in attesa.','PHP errors'=>'Errori PHP','No error log is active.'=>'Nessun registro degli errori attivo.','No serious errors in the last 24 hours.'=>'Nessun errore grave nelle ultime 24 ore.','%d serious PHP error in the last 24 hours. Details in wp-content/debug.log.'=>'%d errore PHP grave nelle ultime 24 ore. Dettagli in wp-content/debug.log.' . "\0" . '%d errori PHP gravi nelle ultime 24 ore. Dettagli in wp-content/debug.log.','Backup'=>'Backup','The last backup (UpdraftPlus) was %d day ago.'=>'L’ultimo backup (UpdraftPlus) risale a %d giorno fa.' . "\0" . 'L’ultimo backup (UpdraftPlus) risale a %d giorni fa.','Please check the schedule in UpdraftPlus.'=>'Verificare la pianificazione in UpdraftPlus.','Jetpack is connected. The backup status is shown under Jetpack › VaultPress Backup.'=>'Jetpack è connesso. Lo stato dei backup è visibile in Jetpack › VaultPress Backup.','Missing pages (404)'=>'Pagine mancanti (404)','%d address not found in the last 24 hours.'=>'%d indirizzo non trovato nelle ultime 24 ore.' . "\0" . '%d indirizzi non trovati nelle ultime 24 ore.','Please check under SEO › Redirects.'=>'Verificare in SEO › Reindirizzamenti.','Problem on %s'=>'Problema su %s','Overview:'=>'Panoramica:','Updates are not active: please enter a GitHub access token under MomentumLab › Settings.'=>'Gli aggiornamenti non sono attivi: inserire un token di accesso GitHub in MomentumLab › Impostazioni.','%d problem'=>'%d problema' . "\0" . '%d problemi']];